import React from 'react';
import ChatInput from './ChatInput';
import PromptHeader from './PromptHeader';
import DatasetCard from './DatasetCard';
import ModelCard from './ModelCard';

const ChatContainer = ({ chatSubmitted, setChatSubmitted, currentPrompt, setCurrentPrompt }) => {
  const handleNewProject = () => {
    setChatSubmitted(false);
    setCurrentPrompt('');
  };

  return (
    <div className="w-full">
      {!chatSubmitted ? (
        <ChatInput 
          setChatSubmitted={setChatSubmitted}
          setCurrentPrompt={setCurrentPrompt}
        />
      ) : (
        <div className="space-y-8">
          {/* Prompt Header - Animated to top */}
          <div className="animate-slide-up">
            <PromptHeader prompt={currentPrompt} />
          </div>

          {/* New Project Button */}
          <div className="flex justify-center">
            <button
              onClick={handleNewProject}
              className="px-6 py-3 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white rounded-lg font-medium transition-all shadow-lg hover:shadow-xl"
            >
              Create New Project
            </button>
          </div>

          {/* Cards Container */}
          <div className="grid md:grid-cols-2 gap-8 animate-fade-in">
            <div className="animate-fade-in" style={{ animationDelay: '0.2s' }}>
              <DatasetCard />
            </div>
            <div className="animate-fade-in" style={{ animationDelay: '0.4s' }}>
              <ModelCard />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ChatContainer;
